begin;
do $$declare st uuid;pa uuid;ad uuid;mg uuid;mid uuid;tid uuid;sv timestamptz;nv timestamptz;pv timestamptz;data jsonb;today date:=(now() at time zone 'Asia/Seoul')::date;
begin
select id into st from public.cheongla_profiles where role='student' and approval_status='approved' and membership_state='active' limit 1;
select id into pa from public.cheongla_profiles where role='parent' and approval_status='approved' and membership_state='active' limit 1;
select id into ad from public.cheongla_profiles where is_app_admin and approval_status='approved' limit 1;
select id into mg from public.cheongla_profiles where role='manager' and approval_status='approved' limit 1;
if st is null or pa is null or ad is null or mg is null then raise exception '검증 계정 없음';end if;
insert into public.cheongla_parent_students(parent_id,student_id,created_by) values(pa,st,ad) on conflict do nothing;
insert into public.cheongla_meal_forms(month,deadline,unit_price)values('2097-11-01','2097-10-28',7500);
insert into public.cheongla_meal_submissions(month,student_id,student_name,lunch,dinner)values('2097-11-01',st,'휴지통 검증 학생',array['2097-11-01'::date],array[]::date[])returning updated_at into sv;
perform set_config('request.jwt.claim.sub',ad::text,true);
mid:=public.cheongla_save_meal_bill_v2('2097-11-01',st,today,0,'검증',sv,null);
select updated_at into nv from public.cheongla_meal_bills where id=mid;
perform public.cheongla_publish_meal_bill(mid,'publish',nv);
select updated_at into nv from public.cheongla_meal_bills where id=mid;
perform public.cheongla_set_fee_payment('meal',mid,true,nv,null);
select updated_at into pv from cheongla_private.fee_payments where notice_kind='meal' and notice_id=mid;
perform set_config('request.jwt.claim.sub',mg::text,true);
begin perform public.cheongla_archive_meal_submission('2097-11-01',st,sv,nv,pv,null);raise exception 'FAIL manager archive';exception when insufficient_privilege then null;end;
perform set_config('request.jwt.claim.sub',pa::text,true);
begin perform public.cheongla_archive_meal_submission('2097-11-01',st,sv,nv,pv,null);raise exception 'FAIL parent archive';exception when insufficient_privilege then null;end;
perform set_config('request.jwt.claim.sub',ad::text,true);
begin perform public.cheongla_archive_meal_submission('2097-11-01',st,sv,nv,null,null);raise exception 'FAIL stale payment';exception when raise_exception then if SQLERRM like 'FAIL%'then raise;end if;end;
tid:=public.cheongla_archive_meal_submission('2097-11-01',st,sv,nv,pv,null);
if not exists(select 1 from public.cheongla_meal_submissions where month='2097-11-01' and student_id=st and archived_at is not null) then raise exception 'FAIL source retention';end if;
if not exists(select 1 from cheongla_private.fee_payments where notice_kind='meal' and notice_id=mid and paid_amount=7500 and paid_at is not null) then raise exception 'FAIL paid history lost';end if;
data:=public.cheongla_read_meal_form('2097-11-01');if jsonb_array_length(data->'submissions')<>0 or jsonb_array_length(data->'bills')<>0 then raise exception 'FAIL archived roster visible';end if;
if jsonb_array_length(public.cheongla_deleted_meal_submissions('2097-11-01'))<>1 then raise exception 'FAIL trash absent';end if;
perform set_config('request.jwt.claim.sub',pa::text,true);if jsonb_array_length(public.cheongla_billing_list('2097-11-01')->'items')<>0 then raise exception 'FAIL archived bill visible';end if;
begin perform public.cheongla_collection_context(mid);raise exception 'FAIL archived notification opened';exception when insufficient_privilege then null;end;
perform set_config('request.jwt.claim.sub',ad::text,true);
begin perform public.cheongla_save_meal_bill_v2('2097-11-01',st,today,0,'변경 불가',sv,nv);raise exception 'FAIL archived edit';exception when raise_exception then if SQLERRM like 'FAIL%'then raise;end if;end;
perform public.cheongla_restore_meal_submission(tid);
perform set_config('request.jwt.claim.sub',pa::text,true);
data:=public.cheongla_billing_list('2097-11-01');if not exists(select 1 from jsonb_array_elements(data->'items') x where x->>'id'=mid::text and x->'_payment'->>'paid_at' is not null and (x->'_payment'->>'paid_amount')::integer=7500)then raise exception 'FAIL restored payment visibility';end if;
end;$$;
rollback;
select 'PASS: principal-only paid meal soft archive, stale state rejection, original/payment retention, hidden roster/billing, trash listing, archived edit protection, restore retains paid status. All rolled back.' as result;
